input.command:
for entity in "store\.User[^A-Za-z]" "store\.UserSetting[^A-Za-z]" "store\.UserIdentity[^A-Za-z]" "store\.Memo[^A-Za-z]" "store\.MemoRelation[^A-Za-z]" "store\.MemoShare[^A-Za-z]" "store\.Attachment[^A-Za-z]" "store\.IdentityProvider[^A-Za-z]" "store\.Inbox[^A-Za-z]" "store\.Reaction[^A-Za-z]" "store\.InstanceSetting[^A-Za-z]"; do
  name=$(echo "$entity" | sed 's/store\\.//; s/\[.*//');
  # Find all Go files outside store/ that reference this entity, extract unique package directories
  count=$(grep -rl "$entity" --include='*.go' . | grep -v '^\./store/' | xargs -I{} dirname {} 2>/dev/null | sort -u | wc -l);
  echo "$name: $count packages";
done

# Exclude store/ subdirs too (store/db/*, store/test are inside the data layer)
